// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateAttempt Mở attempt cho một hoạt động học tập được kích hoạt từ game (bước quest, mini-game)
	// (POST /internal/v1/attempts)
	CreateAttempt(ctx context.Context, request CreateAttemptRequestObject) (CreateAttemptResponseObject, error)
	// GetAttemptResult Lấy trạng thái và kết quả đã chấm của attempt (không có đáp án)
	// (GET /internal/v1/attempts/{attempt_id})
	GetAttemptResult(ctx context.Context, request GetAttemptResultRequestObject) (GetAttemptResultResponseObject, error)
	// CleanupStudentData Soft-delete dữ liệu của học sinh trong module này khi bị dọn do không đăng nhập (ADR-0032)
	// (POST /internal/v1/platform/students/{student_id}:cleanup)
	CleanupStudentData(ctx context.Context, request CleanupStudentDataRequestObject) (CleanupStudentDataResponseObject, error)
	// RestoreStudentData Khôi phục dữ liệu học sinh đã bị dọn khi học sinh đăng nhập lại (ADR-0032 mục 5)
	// (POST /internal/v1/platform/students/{student_id}:restore)
	RestoreStudentData(ctx context.Context, request RestoreStudentDataRequestObject) (RestoreStudentDataResponseObject, error)
	// ListResourceAssignments Liệt kê assignment active của một tài nguyên platform (gán cho tenant, ADR-0029)
	// (GET /internal/v1/platform/tenant-assignments)
	ListResourceAssignments(ctx context.Context, request ListResourceAssignmentsRequestObject) (ListResourceAssignmentsResponseObject, error)
	// ApplyTenantAssignments Gán một tài nguyên platform cho các tenant (tạo assignment active còn thiếu, ADR-0029)
	// (POST /internal/v1/platform/tenant-assignments:apply)
	ApplyTenantAssignments(ctx context.Context, request ApplyTenantAssignmentsRequestObject) (ApplyTenantAssignmentsResponseObject, error)
	// RevokeTenantAssignments Gỡ gán một tài nguyên platform khỏi các tenant (soft-delete assignment, ADR-0028/0029)
	// (POST /internal/v1/platform/tenant-assignments:revoke)
	RevokeTenantAssignments(ctx context.Context, request RevokeTenantAssignmentsRequestObject) (RevokeTenantAssignmentsResponseObject, error)
	// ExecuteTenantCloneStep Thực thi bước clone thuộc module này trong một job clone tenant (saga do module identity điều phối)
	// (POST /internal/v1/platform/tenant-clones/{job_id}/steps)
	ExecuteTenantCloneStep(ctx context.Context, request ExecuteTenantCloneStepRequestObject) (ExecuteTenantCloneStepResponseObject, error)
	// ListTrash Liệt kê bản ghi đã soft-delete của module này (Thùng rác, ADR-0028)
	// (GET /internal/v1/platform/trash)
	ListTrash(ctx context.Context, request ListTrashRequestObject) (ListTrashResponseObject, error)
	// RestoreTrashItem Khôi phục một bản ghi đã soft-delete (đặt lại deleted_at = NULL)
	// (POST /internal/v1/platform/trash/{resource_type}/{resource_id}:restore)
	RestoreTrashItem(ctx context.Context, request RestoreTrashItemRequestObject) (RestoreTrashItemResponseObject, error)
	// AnonymizeUserData Ẩn danh hóa dữ liệu cá nhân của user trong module này (yêu cầu xóa dữ liệu = ẩn danh hóa, ADR-0028 mục 8)
	// (POST /internal/v1/platform/users/{user_id}:anonymize)
	AnonymizeUserData(ctx context.Context, request AnonymizeUserDataRequestObject) (AnonymizeUserDataResponseObject, error)
	// MergeUserData Chuyển dữ liệu của một user sang user đích khi gộp tài khoản trùng (module identity điều phối)
	// (POST /internal/v1/platform/users/{user_id}:merge-into)
	MergeUserData(ctx context.Context, request MergeUserDataRequestObject) (MergeUserDataResponseObject, error)
	// CreateQuestionPlan Tạo bộ câu hỏi cho một trận thi đấu (chỉ render payload, không đáp án)
	// (POST /internal/v1/question-plans)
	CreateQuestionPlan(ctx context.Context, request CreateQuestionPlanRequestObject) (CreateQuestionPlanResponseObject, error)
	// ScorePlanAnswer Chấm một câu trả lời trong trận (server-authoritative) và ghi bằng chứng học tập
	// (POST /internal/v1/question-plans/{plan_id}/answers:score)
	ScorePlanAnswer(ctx context.Context, request ScorePlanAnswerRequestObject) (ScorePlanAnswerResponseObject, error)
	// RevealPlanItem Đáp án đúng và giải thích của một câu đã đóng trong trận (F105)
	// (GET /internal/v1/question-plans/{plan_id}/items/{index}/reveal)
	RevealPlanItem(ctx context.Context, request RevealPlanItemRequestObject) (RevealPlanItemResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// CreateAttempt operation middleware
func (sh *strictHandler) CreateAttempt(w http.ResponseWriter, r *http.Request) {
	var request CreateAttemptRequestObject

	var body CreateAttemptJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.CreateAttempt(ctx, request.(CreateAttemptRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "CreateAttempt")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(CreateAttemptResponseObject); ok {
		if err := validResponse.VisitCreateAttemptResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

